#include "VM.h"
#include <cmath>
#include <unordered_map>
#include <vector>
namespace jspp {
static bool truthy(const js_value&v){switch(v.kind){case JS_VALUE_UNDEFINED:case JS_VALUE_NULL:return false;case JS_VALUE_BOOLEAN:return v.boolean;case JS_VALUE_NUMBER:return v.number!=0&&!std::isnan(v.number);case JS_VALUE_STRING:return !v.string.empty();}return false;}
static bool equal(const js_value&a,const js_value&b,bool strict){if(a.kind==b.kind){if(a.kind==JS_VALUE_NUMBER)return a.number==b.number;if(a.kind==JS_VALUE_BOOLEAN)return a.boolean==b.boolean;if(a.kind==JS_VALUE_STRING)return a.string==b.string;return true;}return !strict&&((a.kind==JS_VALUE_NULL&&b.kind==JS_VALUE_UNDEFINED)||(a.kind==JS_VALUE_UNDEFINED&&b.kind==JS_VALUE_NULL));}
bool execute(const Bytecode&code,js_value&result,std::string&error){std::vector<js_value>stack;std::unordered_map<std::string,js_value>env;auto pop=[&](){auto v=std::move(stack.back());stack.pop_back();return v;};for(const auto&i:code.instructions){switch(i.op){case Op::PushUndefined:stack.push_back({});break;case Op::PushNull:{js_value v;v.kind=JS_VALUE_NULL;stack.push_back(std::move(v));break;}case Op::PushBoolean:{js_value v;v.kind=JS_VALUE_BOOLEAN;v.boolean=i.boolean;stack.push_back(std::move(v));break;}case Op::PushNumber:{js_value v;v.kind=JS_VALUE_NUMBER;v.number=i.number;stack.push_back(std::move(v));break;}case Op::PushString:{js_value v;v.kind=JS_VALUE_STRING;v.string=i.text;stack.push_back(std::move(v));break;}case Op::Load:{auto it=env.find(i.text);if(it==env.end()){error="unknown identifier '"+i.text+"'";return false;}stack.push_back(it->second);break;}case Op::Store:env[i.text]=pop();break;case Op::Pop:if(!stack.empty())stack.pop_back();break;case Op::UnaryPlus:case Op::Negate:{auto v=pop();if(v.kind!=JS_VALUE_NUMBER){error="numeric unary operator requires a number";return false;}if(i.op==Op::Negate)v.number=-v.number;stack.push_back(std::move(v));break;}case Op::Not:{auto v=pop();js_value x;x.kind=JS_VALUE_BOOLEAN;x.boolean=!truthy(v);stack.push_back(std::move(x));break;}default:{if(stack.size()<2){error="invalid bytecode stack";return false;}auto right=pop(),left=pop(),out=js_value{};if(i.op==Op::Add&&left.kind==JS_VALUE_STRING&&right.kind==JS_VALUE_STRING){out.kind=JS_VALUE_STRING;out.string=left.string+right.string;stack.push_back(std::move(out));break;}if(i.op==Op::Equal||i.op==Op::NotEqual||i.op==Op::StrictEqual||i.op==Op::StrictNotEqual){out.kind=JS_VALUE_BOOLEAN;out.boolean=equal(left,right,i.op==Op::StrictEqual||i.op==Op::StrictNotEqual);if(i.op==Op::NotEqual||i.op==Op::StrictNotEqual)out.boolean=!out.boolean;stack.push_back(std::move(out));break;}if(i.op==Op::Less||i.op==Op::LessEqual||i.op==Op::Greater||i.op==Op::GreaterEqual){out.kind=JS_VALUE_BOOLEAN;if(left.kind==JS_VALUE_NUMBER&&right.kind==JS_VALUE_NUMBER){if(i.op==Op::Less)out.boolean=left.number<right.number;else if(i.op==Op::LessEqual)out.boolean=left.number<=right.number;else if(i.op==Op::Greater)out.boolean=left.number>right.number;else out.boolean=left.number>=right.number;}else if(left.kind==JS_VALUE_STRING&&right.kind==JS_VALUE_STRING){if(i.op==Op::Less)out.boolean=left.string<right.string;else if(i.op==Op::LessEqual)out.boolean=left.string<=right.string;else if(i.op==Op::Greater)out.boolean=left.string>right.string;else out.boolean=left.string>=right.string;}else{error="ordering requires two numbers or two strings";return false;}stack.push_back(std::move(out));break;}if(left.kind!=JS_VALUE_NUMBER||right.kind!=JS_VALUE_NUMBER){error="arithmetic requires two numbers (or two strings for '+')";return false;}out.kind=JS_VALUE_NUMBER;if(i.op==Op::Add)out.number=left.number+right.number;else if(i.op==Op::Subtract)out.number=left.number-right.number;else if(i.op==Op::Multiply)out.number=left.number*right.number;else if(i.op==Op::Divide)out.number=left.number/right.number;else if(i.op==Op::Remainder)out.number=std::fmod(left.number,right.number);else{error="invalid arithmetic opcode";return false;}stack.push_back(std::move(out));break;}}}if(stack.size()!=1){error="invalid bytecode completion stack";return false;}result=std::move(stack.back());return true;}
}
